const test = require('node:test');
const assert = require('node:assert/strict');
const { enabled } = require('../newsletter.cjs');
test('only the explicit true setting enables delivery', () => {
  for (const [input, expected] of [['true',true],['false',false],['',false],[undefined,false]]) {
    assert.equal(enabled(input), expected);
  }
  assert.equal(enabled('false'), false);
});
